<section class="panel gal-photo-panel"><div class="section-head"><h2>02 / ภาพความทรงจำ</h2><span><?= count($photos) ?> / 60 ภาพ</span></div><label class="gal-upload" id="gallery-drop"><span class="material-icons" aria-hidden="true">add_photo_alternate</span><strong>เลือกภาพ หรือวางไฟล์ที่นี่</strong><span>JPG, PNG, WebP · ไม่เกิน 5 MB / ภาพ · ครั้งละไม่เกิน 15 ภาพ</span><input type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple id="gallery-upload"></label><p id="gallery-upload-status" role="status"></p><div id="gallery-upload-preview" class="gal-upload-preview"></div><p class="gal-help">เลือกภาพปก ใส่คำบรรยาย และกำหนดลำดับภาพ (เลขน้อยแสดงก่อน) การเปลี่ยนแปลงจะมีผลเมื่อกดบันทึก</p><div class="gal-edit-photos"><?php foreach ($photos as $p): ?><div class="gal-edit-photo"><img src="<?= e(base_url().$p['path']) ?>" alt="<?= e($p['caption']) ?>" loading="lazy"><label class="gal-radio"><input type="radio" name="cover" value="<?= (int)$p['id'] ?>" <?= $p['is_cover'] ? 'checked' : '' ?>> ใช้เป็นภาพปก</label><label>คำบรรยาย / Alt text<input name="photos[<?= $p['id'] ?>][caption]" maxlength="250" value="<?= e($p['caption']) ?>"></label><label>ลำดับ<input type="number" min="0" max="9999" name="photos[<?= $p['id'] ?>][sort_order]" value="<?= (int)$p['sort_order'] ?>" required></label><label class="gal-radio gal-danger"><input type="checkbox" name="photos[<?= $p['id'] ?>][remove]" value="1" data-remove-photo> ลบภาพนี้เมื่อบันทึก</label></div><?php endforeach ?></div></section></div>
<aside><section class="panel stack-form gal-publish"><h2>การเผยแพร่</h2><label>สถานะ<select name="status"><option value="draft" <?= $album['status']==='draft' ? 'selected' : '' ?>>ฉบับร่าง</option><option value="published" <?= $album['status']==='published' ? 'selected' : '' ?>>เผยแพร่บนเว็บไซต์</option></select></label><p class="gal-help">ฉบับร่างจะเห็นเฉพาะผู้ดูแลระบบ ต้องมีอย่างน้อย 1 ภาพก่อนเผยแพร่</p><label>ลำดับอัลบั้ม<input name="sort_order" type="number" min="0" max="9999" required value="<?= (int)$album['sort_order'] ?>"></label><button class="btn" type="submit">บันทึกอัลบั้ม</button><a href="<?= base_url().'admin/gallery' ?>">กลับรายการ</a></section></aside></div></form>
